import React, { useState } from "react";

export default function NgoDashboard({ token, msg, setMsg, events, setEvents, ngoPanel }) {
  const [newEvent, setNewEvent] = useState({
    title: "",
    description: "",
    location: "",
    date: "",
    requiredVolunteers: 0
  });
  const [volunteers, setVolunteers] = useState(null);
  const [donations, setDonations] = useState(null);

  function createEvent(e) {
    e.preventDefault();

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/create-event", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify(newEvent)
    })
      .then(r => r.json())
      .then(d => {
        setMsg(d.msg);
        if (d.event) setEvents([...events, d.event]);
      });
  }

  return (
    <div className="panel">
      <h3>NGO Dashboard</h3>

      {ngoPanel ? (
        <>
          <p><strong>NGO Name:</strong> {ngoPanel.name}</p>
          <p><strong>Total Events:</strong> {ngoPanel.totalEvents}</p>
          <p><strong>Total Volunteers:</strong> {ngoPanel.totalVolunteers}</p>
          <p><strong>Total Donations Received:</strong> ₹{ngoPanel.totalDonations}</p>
        </>
      ) : (
        <p>Loading NGO Overview...</p>
      )}

      <h4>Create New Event</h4>

      <form onSubmit={createEvent}>
        <input
          type="text"
          placeholder="Event Title"
          value={newEvent.title}
          onChange={e => setNewEvent({ ...newEvent, title: e.target.value })}
          required
        />

        <textarea
          placeholder="Event Description"
          value={newEvent.description}
          onChange={e => setNewEvent({ ...newEvent, description: e.target.value })}
        ></textarea>

        <input
          type="text"
          placeholder="Location"
          value={newEvent.location}
          onChange={e => setNewEvent({ ...newEvent, location: e.target.value })}
        />

        <input
          type="date"
          value={newEvent.date}
          onChange={e => setNewEvent({ ...newEvent, date: e.target.value })}
        />

        <input
          type="number"
          placeholder="Required Volunteers"
          value={newEvent.requiredVolunteers}
          onChange={e => setNewEvent({ ...newEvent, requiredVolunteers: e.target.value })}
        />

        <button type="submit">Create Event</button>
      </form>

      <p className="msg">{msg}</p>
      <div style={{marginTop:18}}>
        <button onClick={async ()=>{ if (!token) { setMsg('Login first'); return;} const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/ngo/volunteers',{headers:{Authorization:`Bearer ${token}`}}); const d = await res.json(); setVolunteers(d.volunteers || []); }}>View Volunteers</button>
        <button style={{marginLeft:8}} onClick={async ()=>{ if (!token) { setMsg('Login first'); return;} const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/ngo/donations',{headers:{Authorization:`Bearer ${token}`}}); const d = await res.json(); setDonations(d.donations || []); }}>View Donations</button>
      </div>

      {volunteers && (
        <div style={{marginTop:12}}>
          <h4>Volunteers</h4>
          {volunteers.length ? volunteers.map(v=>(<div key={v.id} style={{padding:8,borderBottom:'1px solid #eee'}}><strong>{v.user_name}</strong> ({v.user_email}) — {v.event_title}</div>)) : <p>No volunteers yet.</p>}
        </div>
      )}

      {donations && (
        <div style={{marginTop:12}}>
          <h4>Donations</h4>
          {donations.length ? donations.map(dn=>(<div key={dn.id} style={{padding:8,borderBottom:'1px solid #eee'}}><strong>{dn.donor_name}</strong> ({dn.donor_email}) — ₹{dn.amount}</div>)) : <p>No donations yet.</p>}
        </div>
      )}
    </div>
  );
}
